function check(input, actual, expected) {
  // Rebuild a tree from its level-order form; returns the nodes in breadth-first order, or null if malformed.
  const parse = (data) => {
    if (!Array.isArray(data) || data.length === 0 || typeof data[0] !== 'number') return null;
    const nodes = [{ val: data[0], left: null, right: null }];
    let i = 1;
    for (let q = 0; q < nodes.length && i < data.length; q++) {
      for (const side of ['left', 'right']) {
        if (i < data.length && data[i] !== null) {
          if (typeof data[i] !== 'number') return null;
          const node = { val: data[i], left: null, right: null };
          nodes[q][side] = node;
          nodes.push(node);
        }
        i++;
      }
    }
    return i < data.length ? null : nodes;
  };
  const inorder = (nodes) => {
    const out = [], stack = [];
    let current = nodes[0];
    while (current || stack.length) {
      while (current) { stack.push(current); current = current.left; }
      current = stack.pop();
      out.push(current.val);
      current = current.right;
    }
    return out;
  };
  const original = parse(input[0]);
  const result = parse(actual);
  if (!original || !result || result.length !== original.length) return false;
  // The in-order walk of a BST with the same values must give the same sorted list.
  const want = inorder(original), got = inorder(result);
  for (let k = 0; k < want.length; k++) if (want[k] !== got[k]) return false;
  // Children come after their parents in breadth-first order, so walk backwards to get heights.
  const height = new Map();
  for (let k = result.length - 1; k >= 0; k--) {
    const left = result[k].left ? height.get(result[k].left) : 0;
    const right = result[k].right ? height.get(result[k].right) : 0;
    if (Math.abs(left - right) > 1) return false;
    height.set(result[k], 1 + Math.max(left, right));
  }
  return true;
}

