function balanceBST(root) {
  // Gather the values in any order, sort them, and split at the upper middle.
  const all = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) continue;
    all.push(node.val);
    queue.push(node.left, node.right);
  }
  all.sort((a, b) => a - b);
  function make(lo, hi) {
    if (lo > hi) return null;
    const mid = Math.ceil((lo + hi) / 2);
    return new TreeNode(all[mid], make(lo, mid - 1), make(mid + 1, hi));
  }
  return make(0, all.length - 1);
}

