function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const small = size === 'small';
  const count = small ? 1 + pick(10) : 800 + pick(201);
  const top = small ? (rand() < 0.7 ? 30 : 100000) : 100000;
  // Distinct values from 1 to top.
  const seen = new Set();
  const order = [];
  while (order.length < count) {
    const value = 1 + pick(top);
    if (!seen.has(value)) { seen.add(value); order.push(value); }
  }
  // Pick a shape: random insertion order, a rising or falling chain, or a zigzag of alternating ends.
  const shape = rand();
  if (shape < 0.2) order.sort((a, b) => a - b);
  else if (shape < 0.35) order.sort((a, b) => b - a);
  else if (shape < 0.5) {
    order.sort((a, b) => a - b);
    const zigzag = [];
    for (let lo = 0, hi = order.length - 1; lo <= hi;) {
      zigzag.push(order[lo++]);
      if (lo <= hi) zigzag.push(order[hi--]);
    }
    order.splice(0, order.length, ...zigzag);
  }
  let root = null;
  for (const value of order) {
    const node = { val: value, left: null, right: null };
    if (!root) { root = node; continue; }
    let at = root;
    for (;;) {
      const side = value < at.val ? 'left' : 'right';
      if (!at[side]) { at[side] = node; break; }
      at = at[side];
    }
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
